import { test as base } from "../helpers/system-control-browser";
import "dotenv/config";
import { randomUUID } from "node:crypto";
import { expect } from "@playwright/test";
import { Pool } from "pg";
import { encode } from "next-auth/jwt";
import { requireTestDatabaseUrl } from "../helpers/foundation-db";
requireTestDatabaseUrl();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const test = base.extend<{ ownerId: string }>({
  ownerId: async ({ context }, runFixture) => {
    const id = randomUUID();
    await pool.query(
      `INSERT INTO "User" (id,email,name,"gmailAuthorized","encryptedRefreshToken","usageBackfillVersion","usageCutoverAt") VALUES ($1,$2,'Gmail Pause Fixture',true,'unused-fixture',1,NOW())`,
      [id, `${id}@example.test`],
    );
    const salt = "authjs.session-token",
      token = await encode({
        secret: process.env.AUTH_SECRET!,
        salt,
        token: { userId: id, sub: id },
      });
    await context.addCookies([
      {
        name: salt,
        value: token,
        domain: "localhost",
        path: "/",
        httpOnly: true,
        sameSite: "Lax",
      },
    ]);
    try {
      await runFixture(id);
    } finally {
      await pool.query(`DELETE FROM "User" WHERE id=$1`, [id]);
    }
  },
});
test.afterAll(() => pool.end());
test("credential and domain pauses explain recovery and show Reconnect Gmail", async ({
  page,
  ownerId,
}) => {
  await pool.query(
    `UPDATE "User" SET "gmailAuthorized"=false,"gmailPauseReason"='RECONNECT_REQUIRED' WHERE id=$1`,
    [ownerId],
  );
  await page.goto("/settings");
  await expect(
    page.getByRole("button", { name: "Reconnect Gmail", exact: true }),
  ).toBeVisible();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: "Cancelled emails stay cancelled" })
      .first(),
  ).toBeVisible();
  await pool.query(
    `UPDATE "User" SET "gmailPauseReason"='DOMAIN_POLICY' WHERE id=$1`,
    [ownerId],
  );
  await page.reload();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: "workspace administrator" })
      .first(),
  ).toBeVisible();
  const user = (
    await pool.query(`SELECT plan,"gmailAuthorized" FROM "User" WHERE id=$1`, [
      ownerId,
    ])
  ).rows[0];
  expect(user).toMatchObject({ plan: "FREE", gmailAuthorized: false });
});
test("provider cooldown is separate from app allowance and exposes its deadline", async ({
  page,
  ownerId,
}) => {
  await pool.query(
    `UPDATE "User" SET "gmailPauseReason"='PROVIDER_DAILY_LIMIT',"gmailPauseUntil"=NOW()+interval '2 hours' WHERE id=$1`,
    [ownerId],
  );
  await page.goto("/settings");
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: "separate from your Mailloop allowance" })
      .first(),
  ).toBeVisible();
  await expect(
    page
      .getByRole("status")
      .filter({ hasText: "Provider cooldown until" })
      .first(),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Gmail sending paused" }),
  ).toBeVisible();
  const quota = await page.request.get("/api/quota");
  expect(quota.ok()).toBe(true);
  expect((await quota.json()).used).toBe(0);
});
